import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    t = int(next(iterator))

    results = []

    for _ in range(t):
        n = int(next(iterator))
        a = []
        for _ in range(n):
            a.append(int(next(iterator)))

        dp = [0] * n

        for i in range(n - 1, -1, -1):
            jump = a[i]
            next_idx = i + jump
            if next_idx < n:
                dp[i] = a[i] + dp[next_idx]
            else:
                dp[i] = a[i]

        results.append(str(max(dp)))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == "__main__":
    solve()
